/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

/** Calendar date of an instant in an IANA time zone. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    year: "numeric", month: "2-digit", day: "2-digit", timeZone,
  }).formatToParts(parseIso(value));
  const part = (type: string) => parts.find((item) => item.type === type)!.value;
  return `${part("year")}-${part("month")}-${part("day")}`;
}

function zonedParts(value: Date, timeZone: string) {
  const parts = new Intl.DateTimeFormat("en-GB", {
    year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit",
    minute: "2-digit", second: "2-digit", hourCycle: "h23", timeZone,
  }).formatToParts(value);
  const get = (type: string) => Number(parts.find((item) => item.type === type)!.value);
  return { year: get("year"), month: get("month"), day: get("day"), hour: get("hour"), minute: get("minute"), second: get("second") };
}

/** UTC instant at which the local calendar day containing reference began. */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const p = zonedParts(reference, timeZone);
  const target = Date.UTC(p.year, p.month - 1, p.day);
  let guess = target;
  for (let i = 0; i < 4; i++) {
    const q = zonedParts(new Date(guess), timeZone);
    const represented = Date.UTC(q.year, q.month - 1, q.day, q.hour, q.minute, q.second);
    guess += target - represented;
  }
  return toIsoTimestamp(new Date(guess));
}

/** True when a due date exists and has already passed. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  const dayStart = startOfLocalDay(reference, timeZone).slice(0, 10);
  return localDate(dueAt, timeZone) < dayStart;
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The 24-hour window a digest covers, ending at today's `digestHourUtc`. If
 * that hour has not arrived yet on `reference`'s day, the window is the one
 * that ended yesterday — so a job run early never mails an empty digest and
 * then skips the real one.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  const p = zonedParts(reference, timeZone);
  const dayStart = startOfLocalDay(reference, timeZone);
  let end = new Date(new Date(dayStart).getTime() + digestHourUtc * HOUR_MS);
  if (end.getTime() > reference.getTime()) end = new Date(end.getTime() - DAY_MS);
  const previousDay = new Date(end.getTime() - DAY_MS);
  const endParts = zonedParts(end, timeZone);
  // Rebuild both wall-clock boundaries independently so DST days are 23/25h.
  const endDate = `${endParts.year}-${String(endParts.month).padStart(2,"0")}-${String(endParts.day).padStart(2,"0")}`;
  const startParts = zonedParts(previousDay, timeZone);
  const startDate = `${startParts.year}-${String(startParts.month).padStart(2,"0")}-${String(startParts.day).padStart(2,"0")}`;
  const wallTime = (date: string) => {
    const utcGuess = new Date(`${date}T${String(digestHourUtc).padStart(2,"0")}:00:00.000Z`);
    const offsetParts = zonedParts(utcGuess, timeZone);
    const represented = Date.UTC(offsetParts.year, offsetParts.month - 1, offsetParts.day, offsetParts.hour, offsetParts.minute, offsetParts.second);
    return new Date(utcGuess.getTime() + Date.UTC(Number(date.slice(0,4)), Number(date.slice(5,7))-1, Number(date.slice(8,10)), digestHourUtc) - represented);
  };
  end = wallTime(endDate);

  return {
    start: toIsoTimestamp(wallTime(startDate)),
    end: toIsoTimestamp(end),
  };
}

